<template><div class="sections-page"><aside class="sections-sidebar"><div class="brand"><img src="/logo.png"><div><b>EduMatch</b><small>{{ roleLabel }} Portal</small></div></div><nav><router-link :to="`/${role}/dashboard`"><i class="fas fa-home"></i>Dashboard</router-link><router-link :to="`/${role}/sections`" class="active"><i class="fas fa-layer-group"></i>Manage Sections</router-link><router-link :to="role==='admin'?'/admin/users':'/secretary/students'"><i class="fas fa-users"></i>{{ role==='admin'?'User Management':'Student Records' }}</router-link></nav></aside><main><header><div><p>School structure</p><h1>Manage Sections</h1><span>Create and maintain capacity-aware sections without changing historical records.</span></div><button class="primary" @click="openCreate"><i class="fas fa-plus"></i>Add section</button></header><section class="toolbar"><label><i class="fas fa-search"></i><input v-model="search" placeholder="Search section, grade, strand"></label><select v-model="year"><option value="all">All school years</option><option v-for="v in years" :key="v">{{v}}</option></select><select v-model="status"><option value="all">All statuses</option><option value="active">Active</option><option value="archived">Archived</option></select></section><p v-if="error" class="message error">{{error}}</p><section class="cards"><article v-for="s in filtered" :key="s.id"><div class="card-head"><div><span class="status" :class="s.status">{{s.status}}</span><h2>{{s.name}}</h2><p>Grade {{s.gradeLevel}}<template v-if="s.strand"> · {{s.strand}}</template></p></div><div class="actions"><button title="Edit" @click="openEdit(s)"><i class="fas fa-pen"></i></button><button :title="s.isActive?'Archive':'Restore'" @click="toggleArchive(s)"><i :class="s.isActive?'fas fa-box-archive':'fas fa-rotate-left'"></i></button><button class="danger" title="Delete" @click="remove(s)"><i class="fas fa-trash"></i></button></div></div><div class="meter"><div><span>Enrollment</span><strong>{{s.enrolledCount}} / {{s.capacity}}</strong></div><progress :value="s.enrolledCount" :max="s.capacity"></progress><small>{{s.availableSlots}} available slot{{s.availableSlots===1?'':'s'}}</small></div><footer><span><i class="far fa-calendar"></i>{{s.schoolYear}}</span><span><i class="fas fa-users"></i>{{Math.round((s.enrolledCount/s.capacity)*100)||0}}% full</span></footer></article><div v-if="!loading&&!filtered.length" class="empty"><i class="fas fa-layer-group"></i><b>No matching sections</b><span>Adjust the filters or create a new section.</span></div></section></main><div v-if="modal" class="modal"><form @submit.prevent="save"><header><div><h2>{{editing?'Edit section':'Add section'}}</h2><p>Section capacity is enforced automatically during enrollment.</p></div><button type="button" @click="modal=false"><i class="fas fa-times"></i></button></header><div class="form-grid"><label><span>Section name *</span><input v-model.trim="form.name" required maxlength="80"></label><label><span>Grade level *</span><select v-model="form.gradeLevel" required><option v-for="g in ['7','8','9','10','11','12']" :key="g">{{g}}</option></select></label><label><span>Strand</span><select v-model="form.strand"><option value="">Not applicable</option><option v-for="v in ['STEM','ABM','HUMSS','GAS','TVL']" :key="v">{{v}}</option></select></label><label><span>School year *</span><input v-model="form.schoolYear" required pattern="\d{4}-\d{4}" placeholder="2026-2027"></label><label><span>Student capacity *</span><input v-model.number="form.capacity" type="number" min="1" max="200" required></label></div><p v-if="modalError" class="message error">{{modalError}}</p><footer><button type="button" class="secondary" @click="modal=false">Cancel</button><button class="primary" :disabled="saving">{{saving?'Saving...':'Save section'}}</button></footer></form></div></div></template>
<script setup>
import {computed,onMounted,reactive,ref} from 'vue';import axios from 'axios';import {useAuthStore,resolveApiBaseUrl} from '../../stores/auth.js';
const auth=useAuthStore(),role=computed(()=>auth.user?.role==='secretary'?'secretary':'admin'),roleLabel=computed(()=>role.value==='admin'?'Admin':'Secretary'),sections=ref([]),loading=ref(false),error=ref(''),search=ref(''),year=ref('all'),status=ref('all'),modal=ref(false),editing=ref(null),saving=ref(false),modalError=ref('');const form=reactive({name:'',gradeLevel:'10',strand:'',schoolYear:`${new Date().getFullYear()}-${new Date().getFullYear()+1}`,capacity:40});const api=computed(()=>`${resolveApiBaseUrl()}/${role.value}/manage-sections`),cfg=()=>({headers:{Authorization:`Bearer ${auth.token}`}});const years=computed(()=>[...new Set(sections.value.map(s=>s.schoolYear))]);const filtered=computed(()=>sections.value.filter(s=>(year.value==='all'||s.schoolYear===year.value)&&(status.value==='all'||s.status===status.value)&&[s.name,s.gradeLevel,s.strand,s.schoolYear].join(' ').toLowerCase().includes(search.value.toLowerCase())));async function load(){loading.value=true;error.value='';try{sections.value=(await axios.get(api.value,cfg())).data?.sections||[]}catch(e){error.value=e.response?.data?.message||'Unable to load sections'}finally{loading.value=false}}function reset(){Object.assign(form,{name:'',gradeLevel:'10',strand:'',schoolYear:`${new Date().getFullYear()}-${new Date().getFullYear()+1}`,capacity:40})}function openCreate(){editing.value=null;reset();modalError.value='';modal.value=true}function openEdit(s){editing.value=s;Object.assign(form,{name:s.name,gradeLevel:s.gradeLevel,strand:s.strand,schoolYear:s.schoolYear,capacity:s.capacity});modalError.value='';modal.value=true}async function save(){saving.value=true;modalError.value='';try{editing.value?await axios.put(`${api.value}/${editing.value.id}`,form,cfg()):await axios.post(api.value,form,cfg());modal.value=false;await load()}catch(e){modalError.value=e.response?.data?.message||'Unable to save section'}finally{saving.value=false}}async function toggleArchive(s){if(!confirm(`${s.isActive?'Archive':'Restore'} ${s.name}?`))return;try{await axios.patch(`${api.value}/${s.id}/archive`,{archived:s.isActive},cfg());await load()}catch(e){error.value=e.response?.data?.message||'Unable to update section'}}async function remove(s){if(!confirm(`Permanently delete ${s.name}? Referenced sections cannot be deleted.`))return;try{await axios.delete(`${api.value}/${s.id}`,cfg());await load()}catch(e){error.value=e.response?.data?.message||'Unable to delete section'}}onMounted(load);
</script>
<style scoped>
.sections-page{min-height:100vh;background:#f8fafc;color:#0f172a;display:grid;grid-template-columns:250px 1fr;font-family:Inter,system-ui}.sections-sidebar{background:#fff;border-right:1px solid #e2e8f0;padding:1.2rem}.brand{display:flex;align-items:center;gap:.7rem;padding:.5rem}.brand img{width:42px}.brand div{display:grid}.brand small{color:#64748b}.sections-sidebar nav{display:grid;gap:.35rem;margin-top:2rem}.sections-sidebar a{display:flex;gap:.7rem;align-items:center;padding:.8rem;border-radius:10px;color:#475569;text-decoration:none;font-weight:700}.sections-sidebar a.active{background:#eaf6e5;color:#3f7f2a}main{padding:2rem;min-width:0}main>header{display:flex;justify-content:space-between;align-items:center;gap:1rem}header p{margin:0;color:#4f8a35;text-transform:uppercase;font-size:.75rem;font-weight:800}h1{margin:.15rem 0}header span{color:#64748b}.primary,.secondary,.actions button{border:0;border-radius:10px;padding:.72rem 1rem;font-weight:800;cursor:pointer}.primary{background:#4f8a35;color:#fff}.secondary{background:#eef2f7}.toolbar{display:flex;gap:.7rem;margin:1.5rem 0;background:#fff;padding:1rem;border:1px solid #e2e8f0;border-radius:14px}.toolbar label{flex:1;display:flex;align-items:center;gap:.5rem}.toolbar input,.toolbar select,.toolbar+select,select,input{border:1px solid #cbd5e1;border-radius:9px;padding:.7rem;background:#fff}.toolbar input{width:100%;border:0;outline:0}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:1rem}.cards article{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:1.1rem}.card-head{display:flex;justify-content:space-between;gap:.7rem}.card-head h2{margin:.35rem 0 .1rem}.card-head p{margin:0;color:#64748b}.status{font-size:.68rem;text-transform:uppercase;font-weight:900;padding:.2rem .45rem;border-radius:99px}.status.active{background:#dcfce7;color:#166534}.status.archived{background:#e2e8f0;color:#475569}.actions{display:flex;gap:.3rem}.actions button{padding:.5rem;background:#f1f5f9}.actions .danger{color:#dc2626}.meter{margin:1.2rem 0}.meter div,article footer{display:flex;justify-content:space-between}.meter progress{width:100%;height:8px;margin:.6rem 0}.meter small,article footer{color:#64748b}article footer{border-top:1px solid #edf2f7;padding-top:.8rem;font-size:.78rem}.empty{grid-column:1/-1;padding:4rem;text-align:center;display:grid;gap:.5rem;color:#64748b}.modal{position:fixed;inset:0;background:#0f172a99;display:grid;place-items:center;padding:1rem}.modal form{width:min(600px,100%);background:#fff;border-radius:18px;padding:1.3rem}.modal header,.modal footer{display:flex;justify-content:space-between;align-items:center}.modal header button{border:0;background:none}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin:1.2rem 0}.form-grid label{display:grid;gap:.4rem;font-weight:700}.modal footer{justify-content:flex-end;gap:.6rem}.message{padding:.8rem;border-radius:9px}.error{background:#fef2f2;color:#b91c1c}@media(max-width:760px){.sections-page{grid-template-columns:1fr}.sections-sidebar{display:none}main{padding:1rem}main>header,.toolbar{align-items:stretch;flex-direction:column}.form-grid{grid-template-columns:1fr}}
.sections-sidebar{background:linear-gradient(180deg,#fff 0%,#f8fafc 100%);border-right-color:#e5e7eb;box-shadow:4px 0 18px rgba(15,23,42,.04)}
.brand{padding-bottom:1.2rem;border-bottom:1px solid #e5e7eb}.brand img{width:44px;height:44px;object-fit:contain}
.sections-sidebar a{min-height:44px;box-sizing:border-box;border-radius:12px;transition:background .18s ease,color .18s ease,transform .18s ease}
.sections-sidebar a:hover{background:#f1f5f9;color:#1e4307;transform:translateX(2px)}
.sections-sidebar a i{display:grid;width:24px;place-items:center}.sections-sidebar a.active{background:linear-gradient(135deg,#eaf6e5,#f5faef);box-shadow:inset 3px 0 #69aa47}
</style>
